package main

import "fmt"

func tran(a, b int) int {
	t := 0
	res := 0
	pow := 1
	for {
		t = a / b
		res += pow * (a - (a/b)*b)
		a = t
		pow *= 10
		if t < b {
			break
		}
	}
	res += pow * t
	return res
}

func main() {
	var b int
	fmt.Scan(&b)
	for i := 1; i < b; i++ {
		for j := 1; j < b; j++ {
			fmt.Printf("%d ", tran(i*j, b))
		}
		fmt.Println()
	}
}

